(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const w1y = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const w2x = Math.sin((x + w1x) * 0.012 + t * 0.15) * 20 + Math.cos((y + w1y) * 0.01 - t * 0.1) * 15;
  const w2y = Math.cos((y + w1y) * 0.013 - t * 0.12) * 18 + Math.sin((x + w1x) * 0.011 + t * 0.18) * 12;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*70, 0.05, 2.4],
    [200+Math.sin(t*0.25+6)*90, 220+Math.cos(t*0.45+5)*40, 0.13, 1.3],
    [300+Math.cos(t*0.7+3)*50, 30+Math.sin(t*0.5+2)*60, 0.085, 1.8]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.cos(d*f*0.5 - t*sp*0.4 + 3.0) * 0.3;
  }
  const act = aS/10, inh = iS/10, harm = hS/10;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.06-t*0.7)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const radial = Math.sin(dist*0.03-t*0.8)*0.15;
  const feed = 0.055 + Math.sin(t*0.2)*0.01, kill = 0.062 + Math.cos(t*0.15)*0.008;
  const reaction = Math.tanh((act*(1+feed) - inh*(1-kill) + harm*0.4 + bg*0.3 + spiral + radial)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.1 * Math.max(0, Math.abs(reaction)-0.5);
  const blend = reaction*0.6 + cell*0.25 + micro*0.15, v = blend*0.5+0.5;
  const pal = [[5,12,45],[10,45,85],[15,80,115],[20,130,135],[45,165,120],[180,185,55],[220,160,50],[215,110,55],[185,65,60],[130,35,55],[70,20,50],[30,15,45],[5,12,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.7?1.2 : Math.abs(reaction)>0.5?1.05:1.0;
  const satBoost = 1.0 + Math.max(0, reaction)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*satBoost)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*satBoost)|0
  ];
}
